            insertionIndex += 1;
        }
        lines.splice(insertionIndex, 0, `${LIST_ITEM_PREFIX}${activityPath}`);
    }

    return `${HEADER_DELIMITER}${lineEnding}${lines.join(lineEnding)}${body}`;
